import math

def sigmoid(z):
    """Sigmoid activation: maps any value to (0, 1). Used for binary classification."""
    return 1 / (1 + math.exp(-z))

def relu(z):
    """ReLU activation: max(0, z). Most popular for hidden layers."""
    return max(0, z)

def perceptron(inputs, weights, bias, activation='sigmoid'):
    """Single neuron: computes weighted sum + bias, then applies activation."""
    z = sum(w * x for w, x in zip(weights, inputs)) + bias
    if activation == 'sigmoid':
        return sigmoid(z)
    elif activation == 'relu':
        return relu(z)
    else:
        return z  # linear (no activation)

# === Demonstration ===
print('=== Perceptron: Effect of Weights ===')

# Example: fraud detection inputs
# x1 = transaction amount (normalised), x2 = is_weekend, x3 = overseas

test_cases = [
    ([0.1, 0, 0], 'Small domestic weekday transaction'),
    ([0.9, 1, 1], 'Large overseas weekend transaction (suspicious)'),
    ([0.5, 0, 1], 'Medium overseas weekday'),
]

# Weights tuned to flag large overseas weekend transactions
weights = [0.7, 0.5, 0.8]  # high weight for overseas
bias = -1.2

print(f'Weights: {weights}, Bias: {bias}')
print()
for inputs, label in test_cases:
    output = perceptron(inputs, weights, bias)
    risk = 'HIGH RISK' if output > 0.5 else 'low risk'
    print(f'{label}')
    print(f'  inputs={inputs} → sigmoid output={output:.3f} ({risk})')

# Output:
# Small domestic weekday → 0.302 (low risk)
# Large overseas weekend → 0.817 (HIGH RISK)
# Medium overseas weekday → 0.551 (HIGH RISK)

